"""Modern JavaScript language and browser application foundations."""
from ._catalog import build_guided_catalog

ANALOGY = "JavaScript describes values and operations, then the runtime schedules the work and updates the environment: the browser can render a page, while Node.js can serve requests or run tools."
CATEGORIES = [
    {"id": "language", "title": "Language Foundations", "color": "lemon", "blurb": "Values, types, operators, control flow and predictable error handling."},
    {"id": "functions", "title": "Functions, Objects & Modules", "color": "sky", "blurb": "Model reusable behavior and data with clear module boundaries."},
    {"id": "async", "title": "Asynchronous JavaScript & Web APIs", "color": "mint", "blurb": "Understand promises, the event loop, fetch and cancellation."},
    {"id": "browser", "title": "Browser UI, DOM & Accessibility", "color": "peach", "blurb": "Build responsive interactions using semantic, accessible browser features."},
    {"id": "quality", "title": "Testing, Security & Performance", "color": "lilac", "blurb": "Ship maintainable JavaScript with careful boundaries and evidence."},
]

_ROWS = [
    # Language foundations
    ("What JavaScript Is and Why It Is Used", "language", "basic", "JavaScript is a dynamic, multi-paradigm language standardized as ECMAScript. Browsers use it for interactive interfaces, and server runtimes such as Node.js use it for APIs, automation and tools.", "const message = 'Hello, JavaScript';\nconsole.log(message);"),
    ("Values, Bindings and const", "language", "basic", "A binding gives a name to a value. const prevents rebinding the name, not mutation of an object it references; use let when reassignment is part of the intended flow.", "const user = { name: 'Ari' };\nuser.name = 'Sam'; // object may change\n// user = {} would fail"),
    ("Primitive Types and typeof", "language", "basic", "JavaScript primitives include string, number, bigint, boolean, undefined, symbol and null. typeof null is a historical exception that returns object, so test null explicitly.", "typeof 'hello'; // 'string'\nvalue === null; // explicit null check"),
    ("Equality and Type Coercion", "language", "basic", "Strict equality compares without converting unlike types first. Loose equality performs coercion and can produce surprising results, so use === unless a deliberate conversion is intended.", "0 == false;  // true\n0 === false; // false"),
    ("Truthy and Falsy Values", "language", "basic", "Conditions convert values to booleans. Values such as 0, empty string, null, undefined, NaN and false are falsy; empty arrays and objects are truthy.", "if (items.length) {\n  render(items);\n}"),
    ("Nullish Coalescing and Optional Chaining", "language", "basic", "Optional chaining stops a property or call access when its base is nullish. Nullish coalescing supplies a fallback only for null or undefined, preserving valid values such as zero and empty text.", "const label = user?.profile?.label ?? 'Guest';"),
    ("Strings, Templates and Unicode", "language", "basic", "Template literals interpolate expressions and support multiline text. JavaScript string indexes count UTF-16 code units, so a visible Unicode symbol may occupy more than one index position.", "const message = `Hello, ${name}!`;\n[...message].length; // code points"),
    ("Numbers, NaN and Precision", "language", "intermediate", "JavaScript Number uses IEEE 754 double precision. Many decimal fractions cannot be represented exactly, and NaN is not equal to itself; use safe integer checks or decimal-aware strategies for money.", "0.1 + 0.2; // 0.30000000000000004\nNumber.isNaN(result);"),
    ("BigInt and Large Integers", "language", "intermediate", "BigInt represents integers beyond Number's safe range. It cannot be mixed directly with Number arithmetic, and JSON.stringify does not serialize it without an explicit conversion policy.", "const id = 9007199254740993n;\nconst text = id.toString();"),
    ("Operators, Precedence and Parentheses", "language", "basic", "Operator precedence determines how an expression is grouped. Parentheses make intent clear, especially when mixing arithmetic, comparison, logical operators and nullish fallbacks.", "const allowed = isAdmin || (isOwner && isOpen);"),
    ("Conditions and Switch", "language", "basic", "if/else and switch choose behavior from values. Use switch for a finite set of discrete cases and include a default path when an unexpected value needs handling.", "switch (status) {\n  case 'ready': start(); break;\n  default: showPending();\n}"),
    ("Loops and Iteration", "language", "basic", "for and while loops execute repeatedly while a condition holds. Iteration protocols also power for...of; always make the termination condition and mutation easy to follow.", "for (const item of items) {\n  process(item);\n}"),
    ("Arrays and Array Methods", "language", "basic", "Arrays are ordered, mutable collections. map transforms each item, filter keeps matching items and reduce accumulates a result; choose the method that expresses the intent and avoid accidental mutation.", "const names = users.map(user => user.name);"),
    ("Map, Set and Weak Collections", "language", "intermediate", "Map stores key-value pairs with keys of any type, and Set stores unique values. WeakMap and WeakSet do not keep object keys alive, making them useful for metadata tied to object lifetime.", "const visited = new Set(urls);\nconst countById = new Map();"),
    ("Destructuring and Spread", "language", "basic", "Destructuring reads values from arrays and objects into bindings. Spread copies iterable items or enumerable object properties shallowly, so nested objects remain shared references.", "const { id, ...publicUser } = record;\nconst next = [...items, newItem];"),
    ("Error Objects and try/catch", "language", "basic", "Throw Error objects with useful messages and catch failures at a boundary that can recover, add context or report them. Catching and ignoring an error hides the failure from callers.", "try {\n  await save(record);\n} catch (error) {\n  report(error);\n}"),
    # Functions, objects and modules
    ("Function Declarations and Expressions", "functions", "basic", "Functions package behavior behind a callable boundary. Declarations are hoisted differently from const-bound function expressions, so declare them in a way that keeps initialization and use understandable.", "function add(a, b) { return a + b; }\nconst multiply = (a, b) => a * b;"),
    ("Arrow Functions and this", "functions", "basic", "Arrow functions capture this from their surrounding scope and do not have their own arguments or prototype. Use them for callbacks, while methods may need a method syntax with dynamic this.", "const handler = event => this.handle(event);"),
    ("Default and Rest Parameters", "functions", "basic", "Default parameters apply when an argument is undefined, while rest parameters collect remaining arguments into an array. Defaults can be expressions, including values from earlier parameters.", "function page(items, size = 20, ...flags) {\n  return items.slice(0, size);\n}"),
    ("Closures and Lexical Scope", "functions", "intermediate", "A closure retains access to bindings from the scope where a function was created. This supports private state and callbacks, but captured mutable values can outlive the point where they were first used.", "function makeCounter() {\n  let count = 0;\n  return () => ++count;\n}"),
    ("Callbacks and Higher-Order Functions", "functions", "intermediate", "A higher-order function accepts or returns another function. Callbacks express behavior to run later, but deeply nested callbacks can obscure sequencing and error handling.", "items.filter(isActive).map(formatItem);"),
    ("Objects, Prototypes and Property Lookup", "functions", "intermediate", "Objects store properties and may inherit from a prototype. A lookup checks the object first and then its prototype chain, so inherited properties and own properties are distinct.", "const prototype = { greet() { return 'hi'; } };\nconst user = Object.create(prototype);"),
    ("Classes and Inheritance", "functions", "intermediate", "Classes provide syntax over JavaScript's prototype-based inheritance. Prefer composition when behavior can be shared directly; subclassing couples child behavior to parent assumptions.", "class Admin extends User {\n  canManage() { return true; }\n}"),
    ("Private Fields and Encapsulation", "functions", "intermediate", "Class private fields declared with # are not accessible through ordinary property lookup. Encapsulation keeps an invariant inside the class rather than relying on callers to maintain it.", "class Wallet {\n  #cents = 0;\n  deposit(cents) { this.#cents += cents; }\n}"),
    ("Getters, Setters and Property Descriptors", "functions", "advanced", "Getters and setters run code when a property is read or written; descriptors also control enumerability and writability. Hidden side effects in accessors can make ordinary-looking property operations surprising.", "Object.defineProperty(config, 'token', { enumerable: false });"),
    ("Modules, import and export", "functions", "basic", "ES modules define explicit imports and exports with static dependency structure. Export only stable public interfaces and keep modules focused so dependency direction remains clear.", "export function format(value) { return String(value); }\nimport { format } from './format.js';"),
    ("Package Boundaries and npm", "functions", "intermediate", "package.json declares package metadata, scripts and dependencies. Package exports can define the supported public entry points and prevent consumers from relying on private internal files.", "{\n  \"type\": \"module\",\n  \"scripts\": { \"test\": \"node --test\" }\n}"),
    ("JSON Serialization and Cloning", "functions", "intermediate", "JSON.stringify and parse serialize JSON-compatible values, but lose unsupported values such as functions and undefined properties. structuredClone handles more built-in data types but still has defined limits.", "const clone = structuredClone({ settings, items });"),
    # Async and web APIs
    ("The Call Stack and Run-to-Completion", "async", "basic", "JavaScript runs a task to completion on its current thread before processing another task. A long synchronous loop blocks input, rendering and timers even if the loop appears simple.", "console.log('first');\nqueueMicrotask(() => console.log('later'));\nconsole.log('second');"),
    ("The Event Loop and Task Queues", "async", "intermediate", "The browser event loop coordinates tasks, microtasks, rendering opportunities and I/O callbacks. Promise reactions run as microtasks, generally before the next task, so recursive microtasks can starve rendering.", "setTimeout(() => console.log('task'), 0);\nPromise.resolve().then(() => console.log('microtask'));"),
    ("Promises and Chaining", "async", "basic", "A Promise represents a future fulfillment or rejection. then returns a new Promise, so return values and thrown errors flow through the chain to the next handler.", "loadUser(id)\n  .then(user => loadOrders(user.id))\n  .catch(reportError);"),
    ("async/await and Error Boundaries", "async", "basic", "async functions return promises and await pauses that function until a promise settles. try/catch handles rejected awaited work; concurrent independent operations should not be awaited one after another unnecessarily.", "try {\n  const user = await loadUser(id);\n  render(user);\n} catch (error) { showError(error); }"),
    ("Promise.all, allSettled and Race", "async", "intermediate", "Promise.all waits for all inputs or rejects on the first rejection. allSettled reports each outcome, while race and any express different first-settlement strategies; select based on the failure policy needed.", "const [profile, alerts] = await Promise.all([loadProfile(), loadAlerts()]);"),
    ("Timers and Scheduling", "async", "basic", "setTimeout and setInterval schedule callbacks no earlier than their requested delay; they do not reserve exact execution times. Clear timers when work is no longer needed and avoid intervals that overlap slow async operations.", "const timer = setTimeout(refresh, 1000);\nclearTimeout(timer);"),
    ("Fetch, HTTP Status and JSON", "async", "basic", "fetch resolves for HTTP error responses such as 404, so check response.ok before using a body as success data. Parse JSON explicitly and handle network errors separately from application status.", "const response = await fetch('/api/items');\nif (!response.ok) throw new Error(`HTTP ${response.status}`);\nconst items = await response.json();"),
    ("AbortController and Request Cancellation", "async", "intermediate", "AbortController signals cancellation to APIs such as fetch. Abort obsolete requests when the user changes the selected item or a component is disposed, and handle AbortError as expected cancellation.", "const controller = new AbortController();\nfetch(url, { signal: controller.signal });\ncontroller.abort();"),
    ("Streams and Backpressure", "async", "advanced", "Readable streams deliver chunks over time and can apply backpressure when a consumer is slower than a producer. Respect reader cancellation and release locks when stream processing finishes.", "const reader = response.body.getReader();\nconst { value, done } = await reader.read();"),
    # Browser UI and accessibility
    ("The DOM and Safe Updates", "browser", "basic", "The DOM is the browser's object model of a document. Updating textContent or properties is safe for plain text, while assigning untrusted strings to innerHTML can create script injection vulnerabilities.", "const heading = document.querySelector('h1');\nheading.textContent = userTitle;"),
    ("Events, Bubbling and Delegation", "browser", "basic", "DOM events can bubble from a target through its ancestors. Delegation handles many child controls with one listener, but inspect event.target and use closest within the intended container.", "list.addEventListener('click', event => {\n  const button = event.target.closest('button[data-id]');\n  if (button) openItem(button.dataset.id);\n});"),
    ("Forms, Labels and Validation", "browser", "basic", "Native form controls provide keyboard and accessibility behavior. Associate labels, validate input at both client and server boundaries, and show a useful message beside the field that needs correction.", "const form = document.querySelector('form');\nform.addEventListener('submit', event => { event.preventDefault(); });"),
    ("Keyboard Access and Focus", "browser", "intermediate", "Interactive controls should work with keyboard input and expose visible focus. Prefer native buttons and links, manage focus after dialogs or navigation, and do not use tabindex to create a confusing custom order.", "button.addEventListener('click', save);\nbutton.addEventListener('keydown', handleShortcut);"),
    ("Semantic HTML and ARIA", "browser", "intermediate", "Semantic HTML communicates roles and behavior to browsers and assistive technology. ARIA can add missing semantics, but should not replace a native element that already provides the required behavior.", "<button type=\"button\" aria-expanded=\"false\">Details</button>"),
    ("Rendering and requestAnimationFrame", "browser", "intermediate", "requestAnimationFrame schedules visual updates before a browser paint. Batch reads and writes to avoid layout thrashing and respect reduced-motion preferences for nonessential movement.", "requestAnimationFrame(() => {\n  panel.style.transform = `translateX(${offset}px)`;\n});"),
    ("Storage, Cookies and Browser State", "browser", "intermediate", "localStorage and sessionStorage store strings per origin and can be unavailable or quota-limited. Do not store secrets in browser storage; choose cookies or server storage according to sensitivity and lifetime.", "try { localStorage.setItem('theme', 'dark'); }\ncatch { /* storage may be unavailable */ }"),
    ("Service Workers and Offline Caching", "browser", "advanced", "A service worker can intercept requests and cache selected assets to support offline experiences. Cache versioning and update rules must avoid serving stale application code with incompatible data.", "navigator.serviceWorker.register('/service-worker.js');"),
    # Quality, security and performance
    ("Testing JavaScript with Node Test Runner", "quality", "basic", "Tests encode expected behavior and make regressions visible. Test observable outputs, edge cases and failure behavior, and keep tests deterministic by controlling clocks, randomness and network dependencies.", "import test from 'node:test';\nimport assert from 'node:assert/strict';\ntest('adds values', () => assert.equal(add(2, 3), 5));"),
    ("Linting and Formatting", "quality", "basic", "A linter finds suspicious or inconsistent patterns while a formatter standardizes layout. Keep formatting mechanical and use lint rules that catch real defects without overwhelming the signal with arbitrary style warnings.", "npx eslint src/\nnpx prettier --check src/"),
    ("TypeScript Boundaries and Runtime Validation", "quality", "intermediate", "Static types catch many mistakes during development, but they disappear at runtime. Validate untrusted JSON, URL parameters and storage values at the boundary before treating them as a trusted type.", "const value = JSON.parse(raw);\nif (typeof value.name !== 'string') throw new TypeError('Invalid name');"),
    ("Security: XSS and Trusted Rendering", "quality", "intermediate", "Cross-site scripting occurs when untrusted data becomes executable markup or script. Use text nodes and safe templating by default, sanitize only when rich HTML is required, and deploy a considered content security policy.", "output.textContent = userInput; // safe text, not HTML"),
    ("Dependency and Supply Chain Hygiene", "quality", "intermediate", "Dependencies expand the code and trust surface of an application. Review direct and transitive packages, lock dependency versions, update deliberately and monitor advisories from authoritative sources.", "npm ci\nnpm audit --omit=dev"),
    ("Performance Profiling and Memory Leaks", "quality", "advanced", "Profile before optimizing so time is spent on measured bottlenecks. Retained event listeners, timers, detached DOM nodes and unbounded caches can keep objects alive and increase memory use.", "const controller = new AbortController();\nwindow.addEventListener('resize', onResize, { signal: controller.signal });\ncontroller.abort();"),
    ("Web Workers and CPU-Bound Tasks", "quality", "advanced", "Web Workers move CPU-bound work off the main browser thread and communicate through messages. Data is structured-cloned unless transferable objects are used, and workers cannot manipulate the DOM directly.", "const worker = new Worker(new URL('./worker.js', import.meta.url), { type: 'module' });\nworker.postMessage({ values });"),
]

